	@Test
	void correlatedNotExistsRunsWhenItsOuterBindingsAreAssured() {
		SimpleValueFactory values = SimpleValueFactory.getInstance();
		MapBindingSet thresholdRow = new MapBindingSet(1);
		thresholdRow.setBinding("threshold", values.createLiteral(3));
		BindingSetAssignment threshold = new BindingSetAssignment();
		threshold.setBindingNames(new LinkedHashSet<>(List.of("threshold")));
		threshold.setBindingSets(List.of(thresholdRow));

		StatementPattern type = pattern(values, "node", "urn:type", "nodeType", Double.NaN);
		StatementPattern weight = pattern(values, "node", "urn:weight", "weight", Double.NaN);
		StatementPattern connects = pattern(values, "node", "urn:connects", "neighbor", Double.NaN);
		StatementPattern neighborWeight = pattern(values, "neighbor", "urn:weight", "neighborWeight", Double.NaN);
		Filter lowNeighbor = new Filter(new Join(connects, neighborWeight),
				new Compare(Var.of("neighborWeight"), Var.of("threshold"), Compare.CompareOp.LT));
		Filter source = new Filter(new Join(new Join(threshold, type), weight),
				new Not(new Exists(lowNeighbor)));

		PackedCostModel costs = (query, relationId) -> {
			if (!query.isStatementPattern(relationId)) {
				return Double.NaN;
			}
			return switch (query.statementPatternValue(relationId, 1).stringValue()) {
			case "urn:type" -> 10.0d;
			case "urn:weight" -> 100_000.0d;
			case "urn:connects" -> 2.0d;
			default -> Double.NaN;
			};
		};

		PackedPlanningResult result = PackedCascadesPlanner.optimize(source, OptimizationGoal.root(), costs);

		assertTrue(result.selectedPlan() instanceof Join, result.selectedPlan()::toString);
		Join selected = (Join) result.selectedPlan();
		TupleExpr filteredPrefix;
		if (isStatementPattern(selected.getRightArg(), "urn:weight", "weight")) {
			filteredPrefix = selected.getLeftArg();
		} else {
			assertTrue(isStatementPattern(selected.getLeftArg(), "urn:weight", "weight"),
					result.selectedPlan()::toString);
			filteredPrefix = selected.getRightArg();
		}
		assertTrue(filteredPrefix instanceof Filter, result.selectedPlan()::toString);
		assertTrue(((Filter) filteredPrefix).getCondition() instanceof Not, result.selectedPlan()::toString);
		assertTrue(((Not) ((Filter) filteredPrefix).getCondition()).getArg() instanceof Exists,
				result.selectedPlan()::toString);
	}

	@Test
	void boundedCorrelatedSeedAppliesSelectiveAntiJoinBeforeFiniteWeightFanout() {
		SimpleValueFactory values = SimpleValueFactory.getInstance();
		MapBindingSet thresholdRow = new MapBindingSet(1);
		thresholdRow.setBinding("threshold", values.createLiteral(3));
		BindingSetAssignment threshold = new BindingSetAssignment();
		threshold.setBindingNames(new LinkedHashSet<>(List.of("threshold")));
		threshold.setBindingSets(List.of(thresholdRow));

		StatementPattern type = pattern(values, "node", "urn:type", "nodeType", Double.NaN);
		StatementPattern weight = pattern(values, "node", "urn:weight", "weight", Double.NaN);
		ListMemberOperator selectedWeightValues = new ListMemberOperator();
		selectedWeightValues.setArguments(List.of(
				Var.of("weight"),
				new ValueConstant(values.createLiteral(1)),
				new ValueConstant(values.createLiteral(2)),
				new ValueConstant(values.createLiteral(3)),
				new ValueConstant(values.createLiteral(4))));
		Filter selectedWeights = new Filter(weight, selectedWeightValues);
		StatementPattern connects = pattern(values, "node", "urn:connects", "neighbor", Double.NaN);
		StatementPattern neighborWeight = pattern(values, "neighbor", "urn:weight", "neighborWeight",
				Double.NaN);
		Filter lowNeighbor = new Filter(new Join(connects, neighborWeight),
				new Compare(Var.of("neighborWeight"), Var.of("threshold"), Compare.CompareOp.LT));
		Filter source = new Filter(new Join(new Join(threshold, type), selectedWeights),
				new Not(new Exists(lowNeighbor)));

		OptimizationGoal goal = OptimizationGoal.root().asBudgeted(Duration.ofSeconds(30), 4);
		PackedPlanningResult result = PackedCascadesPlanner.optimize(source, goal,
				measuredCorrelatedSchedulingCosts());

		assertTrue(result.selectedPlan() instanceof Join, result.selectedPlan()::toString);
		Join selected = (Join) result.selectedPlan();
		TupleExpr filteredPrefix;
		TupleExpr weightFanout;
		if (containsStatementPattern(selected.getRightArg(), "urn:weight", "weight")) {
			filteredPrefix = selected.getLeftArg();
			weightFanout = selected.getRightArg();
		} else {
			filteredPrefix = selected.getRightArg();
			weightFanout = selected.getLeftArg();
		}
		assertTrue(containsStatementPattern(weightFanout, "urn:weight", "weight"),
				result.selectedPlan()::toString);
		assertTrue(filteredPrefix instanceof Filter
				&& ((Filter) filteredPrefix).getCondition() instanceof Not,
				() -> "The bounded correlated seed must reach predicate readiness before opening the finite weight "
						+ "fanout: " + result.selectedPlan());
		assertTrue(containsStatementPattern(((Filter) filteredPrefix).getArg(), "urn:type", "nodeType"),
				result.selectedPlan()::toString);
	}

	@Test
	void correlatedNotExistsSchedulingIsIndependentOfSyntacticJoinOrder() {
		SimpleValueFactory values = SimpleValueFactory.getInstance();
		MapBindingSet firstWeight = new MapBindingSet(1);
		firstWeight.setBinding("weight", values.createLiteral(1));
		MapBindingSet secondWeight = new MapBindingSet(1);
		secondWeight.setBinding("weight", values.createLiteral(2));
		BindingSetAssignment selectedWeights = new BindingSetAssignment();
		selectedWeights.setBindingNames(new LinkedHashSet<>(List.of("weight")));
		selectedWeights.setBindingSets(List.of(firstWeight, secondWeight));

		MapBindingSet thresholdRow = new MapBindingSet(1);
		thresholdRow.setBinding("threshold", values.createLiteral(3));
		BindingSetAssignment threshold = new BindingSetAssignment();
		threshold.setBindingNames(new LinkedHashSet<>(List.of("threshold")));
		threshold.setBindingSets(List.of(thresholdRow));

		StatementPattern weight = pattern(values, "node", "urn:weight", "weight", Double.NaN);
		StatementPattern type = pattern(values, "node", "urn:type", "nodeType", Double.NaN);
		StatementPattern connects = pattern(values, "node", "urn:connects", "neighbor", Double.NaN);
		StatementPattern neighborWeight = pattern(values, "neighbor", "urn:weight", "neighborWeight", Double.NaN);
		Filter lowNeighbor = new Filter(new Join(connects, neighborWeight),
				new Compare(Var.of("neighborWeight"), Var.of("threshold"), Compare.CompareOp.LT));
		TupleExpr anchorFirstInput = new Join(new Join(new Join(selectedWeights, weight), type), threshold);
		Filter source = new Filter(anchorFirstInput, new Not(new Exists(lowNeighbor)));

		String previous = System.getProperty(
				PackedDependentSubqueryCosting.CORRELATED_DEPENDENT_INVOCATIONS_PROPERTY);
		System.setProperty(PackedDependentSubqueryCosting.CORRELATED_DEPENDENT_INVOCATIONS_PROPERTY, "true");
		PackedPlanningResult result;
		PackedPlanningResult reordered;
		try {
			result = PackedCascadesPlanner
					.optimize(source, OptimizationGoal.root(), measuredCorrelatedSchedulingCosts());
			TupleExpr weightLastInput = new Join(new Join(new Join(threshold, type), weight.clone()),
					selectedWeights.clone());
			reordered = PackedCascadesPlanner.optimize(
					new Filter(weightLastInput, new Not(new Exists(lowNeighbor.clone()))),
					OptimizationGoal.root(), measuredCorrelatedSchedulingCosts());
		} finally {
			if (previous == null) {
				System.clearProperty(PackedDependentSubqueryCosting.CORRELATED_DEPENDENT_INVOCATIONS_PROPERTY);
			} else {
				System.setProperty(PackedDependentSubqueryCosting.CORRELATED_DEPENDENT_INVOCATIONS_PROPERTY,
						previous);
			}
		}

		/*
		 * With the correlated NOT-EXISTS probe charged once per outer invocation (2026-08,
		 * rdf4j.optimizer.packed.correlatedDependentInvocations), probing the fully joined two-row stream beats probing
		 * any wider partial prefix — the anti-join moves to the top of the stream, and it does so for every syntactic
		 * order of the same join.
		 */
		for (PackedPlanningResult planned : List.of(result, reordered)) {
			List<TupleExpr> selectedFactors = joinFactors(planned.selectedPlan());
			assertEquals(1, selectedFactors.size(), planned.selectedPlan()::toString);
			assertTrue(selectedFactors.get(0) instanceof Filter, planned.selectedPlan()::toString);
			Filter root = (Filter) selectedFactors.get(0);
			assertTrue(root.getCondition() instanceof Not, planned.selectedPlan()::toString);
			assertTrue(containsStatementPattern(root.getArg(), "urn:weight", "weight"),
					planned.selectedPlan()::toString);
			assertTrue(root.getBindingNames().contains("weight"), planned.selectedPlan()::toString);
		}
	}

	@Test
	void correlatedDenseSearchCostsEquivalentContinuationInRetainedState() {
		SimpleValueFactory values = SimpleValueFactory.getInstance();
		MapBindingSet thresholdRow = new MapBindingSet(1);
		thresholdRow.setBinding("threshold", values.createLiteral(3));
		BindingSetAssignment threshold = new BindingSetAssignment();
		threshold.setBindingNames(new LinkedHashSet<>(List.of("threshold")));
		threshold.setBindingSets(List.of(thresholdRow));

		StatementPattern type = pattern(values, "node", "urn:type", "nodeType", Double.NaN);
		StatementPattern weight = pattern(values, "node", "urn:weight", "weight", Double.NaN);
		ListMemberOperator selectedWeightValues = new ListMemberOperator();
		selectedWeightValues.setArguments(List.of(
				Var.of("weight"),
				new ValueConstant(values.createLiteral(1)),
				new ValueConstant(values.createLiteral(2))));
		Filter selectedWeights = new Filter(weight, selectedWeightValues);
		StatementPattern connects = pattern(values, "node", "urn:connects", "neighbor", Double.NaN);
		StatementPattern neighborWeight = pattern(values, "neighbor", "urn:neighborWeight", "neighborWeight",
				Double.NaN);
		Filter lowNeighbor = new Filter(new Join(connects, neighborWeight),
				new Compare(Var.of("neighborWeight"), Var.of("threshold"), Compare.CompareOp.LT));
		Filter source = new Filter(new Join(new Join(threshold, type), selectedWeights),
				new Not(new Exists(lowNeighbor)));
		int antiStateId = 1_000_000;
		boolean[] equivalentWeightPathCostedAfterAnti = new boolean[1];

		PackedCostModel costs = new PackedCostModel() {
			@Override
			public double estimateRows(PackedQueryView query, int relationId) {
				if (query.isFilter(relationId)
						&& query.materializeRelation(relationId).getBindingNames().equals(Set.of("node", "weight"))) {
					return 100_000_000.0d;
				}
				if (query.isBindingSetAssignment(relationId)) {
					return query.bindingAssignmentRowCount(relationId);
				}
				if (!query.isStatementPattern(relationId)) {
					return Double.NaN;
				}
				return switch (query.statementPatternValue(relationId, 1).stringValue()) {
				case "urn:type" -> 100.0d;
				case "urn:weight" -> 100_000.0d;
				default -> 2.0d;
				};
			}

			@Override
			public PackedCostSession openSession(PackedQueryView query) {
				return new PackedCostSession() {
					private int nextStateId = 1;

					@Override
					public void estimateLeaf(int relationId, PackedCostContext context, PackedCostEstimate output) {
						double rows = estimateRows(query, relationId);
						if (Double.isFinite(rows)) {
							output.setRows(rows, rows);
							stamp(output);
						}
					}

					@Override
					public void appendFactor(int relationId, PackedCostContext context, PackedCostEstimate output) {
						if (query.isStatementPattern(relationId)
								&& "urn:weight".equals(query.statementPatternValue(relationId, 1).stringValue())
								&& context.evidenceStateId() == antiStateId) {
							equivalentWeightPathCostedAfterAnti[0] = true;
						}
						if (selectedWeightFilter(query, relationId)) {
							output.setContextualRows(Double.NaN, Double.NaN);
						} else if (query.isBindingSetAssignment(relationId)) {
							double rows = context.prefixRows() * query.bindingAssignmentRowCount(relationId);
							output.setContextualRows(rows, query.bindingAssignmentRowCount(relationId));
						} else if (query.isStatementPattern(relationId)
								&& "urn:weight".equals(query.statementPatternValue(relationId, 1).stringValue())
								&& query.prefixBindsStatementComponent(context, relationId, 2)) {
							output.setComponentRows(1.0d, 1.0d);
						} else {
							double rows = estimateRows(query, relationId);
							if (Double.isFinite(rows)) {
								output.setContextualRows(rows, rows);
							}
						}
						stamp(output);
					}

					@Override
					public void refineOperator(int relationId, PackedCostContext context, PackedCostEstimate output) {
						if (selectedWeightFilter(query, relationId)) {
							if (context.prefixRelationCount() > 0) {
								output.setContextualRows(context.leftInputRows(), context.leftInputRows());
							}
						} else if (antiFilter(query, relationId)) {
							output.setContextualRows(Math.max(1.0d, context.leftInputRows() * 0.25d),
									context.leftInputRows());
							output.setEvidenceStateId(antiStateId);
							return;
						} else if (query.isFilter(relationId)) {
							double rows = Math.max(1.0d, context.leftInputRows() * 0.25d);
							output.setContextualRows(rows, rows);
						}
						stamp(output);
					}

					@Override
					public void refineIntermediateJoin(PackedCostContext context, PackedCostEstimate output) {
						if (context.leftInputEvidenceStateId() == antiStateId
								|| context.rightInputEvidenceStateId() == antiStateId) {
							output.setEvidenceStateId(antiStateId);
						} else {
							stamp(output);
						}
					}

					private void stamp(PackedCostEstimate output) {
						output.setEvidenceStateId(nextStateId++);
					}

					private boolean selectedWeightFilter(PackedQueryView view, int relationId) {
						return view.materializeRelation(relationId)instanceof Filter filter
								&& filter.getCondition() instanceof ListMemberOperator;
					}

					private boolean antiFilter(PackedQueryView view, int relationId) {
						return view.materializeRelation(relationId)instanceof Filter filter
								&& filter.getCondition() instanceof Not;
					}
				};
			}

			@Override
			public void estimate(PackedQueryView query, int relationId, PackedCostContext context,
					PackedCostEstimate output) {
				if (query.isFilter(relationId)
						&& query.materializeRelation(relationId).getBindingNames().equals(Set.of("node", "weight"))
						&& context.prefixRelationCount() > 0) {
					output.setContextualRows(100_000_000.0d, 100_000_000.0d);
					return;
				}
				if (query.isBindingSetAssignment(relationId)) {
					double rows = query.bindingAssignmentRowCount(relationId);
					output.setRows(rows, rows);
					return;
				}
				double rows = estimateRows(query, relationId);
				if (query.isStatementPattern(relationId)
						&& "urn:weight".equals(query.statementPatternValue(relationId, 1).stringValue())
						&& query.prefixBindsStatementComponent(context, relationId, 2)) {
					output.setComponentRows(1.0d, 1.0d);
				} else if (Double.isFinite(rows)) {
					output.setRows(rows, rows);
				}
			}
		};

		PackedPlanningResult result = PackedCascadesPlanner.optimize(source, OptimizationGoal.root(), costs);

		assertTrue(equivalentWeightPathCostedAfterAnti[0],
				() -> "The correlated DP must cost an equivalent weight access path in the retained anti state: "
						+ result.selectedPlan());
	}

	@Test
	void deferredFilterUnlockAddsWorkAndShrinksRows() {
		SimpleValueFactory values = SimpleValueFactory.getInstance();
		List<List<String>> writtenOrders = List.of(
				List.of("urn:detail", "urn:threshold", "urn:type"),
				List.of("urn:threshold", "urn:type", "urn:detail"));
		double firstBoundaryRows = Double.NaN;

		for (List<String> writtenOrder : writtenOrders) {
			List<Double> continuationPrefixRows = new ArrayList<>();
			PackedCostModel costs = splitDependencyFilterCosts(continuationPrefixRows);
			Filter source = splitDependencyFilter(values, writtenOrder);
			PackedPlanningResult withFilter = PackedCascadesPlanner
					.optimize(source, OptimizationGoal.root(), costs);

			List<TupleExpr> selectedFactors = joinFactors(withFilter.selectedPlan());
			List<Filter> selectedFilters = selectedFactors.stream()
					.filter(Filter.class::isInstance)
					.map(Filter.class::cast)
					.toList();
			assertEquals(1, selectedFilters.size(), withFilter.selectedPlan()::toString);
			Filter selectedFilter = selectedFilters.get(0);
			List<String> boundaryPredicates = joinFactors(selectedFilter.getArg())
					.stream()
					.map(StatementPattern.class::cast)
					.map(pattern -> pattern.getPredicateVar().getValue().stringValue())
					.sorted()
					.toList();
			/*
			 * The exact lattice must propagate the improved filtered prefix into its continuation instead of preserving
			 * the stale factor-first terminal selected by the former one-slot traversal. The detail lookup is
			 * executable after the filter and is cheaper from the two filtered rows, so it belongs outside the first
			 * assured boundary.
			 */
			assertEquals(List.of("urn:threshold", "urn:type"), boundaryPredicates,
					withFilter.selectedPlan()::toString);
			assertTrue(selectedFactors.stream()
					.anyMatch(factor -> isStatementPattern(factor, "urn:detail", "detail")),
					withFilter.selectedPlan()::toString);

			double inputRows = selectedFilter.getArg().getResultSizeEstimate();
			double filteredRows = inputRows * 0.25d;
			assertEquals(filteredRows, withFilter.outputRows(), 0.0d, withFilter.selectedPlan()::toString);
			assertEquals(42.0d, withFilter.totalCost(), 0.0d, withFilter.selectedPlan()::toString);
			assertTrue(selectedFilter.getCostEstimate() > selectedFilter.getArg().getCostEstimate(),
					() -> "Filter evaluation must add work after its assured prefix: " + withFilter.selectedPlan());

			assertTrue(continuationPrefixRows.contains(filteredRows),
					() -> "The continuation must be costed from the filtered rows. expected=" + filteredRows
							+ ", observed=" + continuationPrefixRows + ", plan=" + withFilter.selectedPlan());
			if (Double.isNaN(firstBoundaryRows)) {
				firstBoundaryRows = filteredRows;
			} else {
				assertEquals(firstBoundaryRows, filteredRows, 0.0d,
						"Physical input order must not change the first assured filter boundary");
			}
		}
	}

